fn to_lowercase(s: &Vec<char>) -> Vec<char> {
    // Requires that the input vector is not empty
    // Ensures that the output vector has the same length as the input vector
    // and that each character is either unchanged or converted to lowercase
    #[verus]
    requires(!s.is_empty());
    ensures(|result: &Vec<char>| {
        result.len() == s.len() &&
        (0..s.len()).all(|i| {
            let c = s[i];
            result[i] == if c >= 'A' && c <= 'Z' {
                (c as u8 + 32) as char
            } else {
                c
            }
        })
    });
    
    s.iter()
        .map(|&c| {
            if c >= 'A' && c <= 'Z' {
                // Convert uppercase ASCII letter to lowercase
                (c as u8 + 32) as char
            } else {
                // Keep the character unchanged
                c
            }
        })
        .collect()
}

